@if($attempts->isEmpty())<div class="empty-state"><x-icon name="clipboard" /><h3>Nenhuma prova registrada</h3><p>As tentativas aparecerão aqui assim que forem iniciadas.</p></div>@else<div class="table-wrap"><table><thead><tr>@if($showStudent??false)<th>Aluno</th><th>Disciplina</th>@endif<th>Tentativa</th><th>Data</th><th>Situação</th><th>Nota final</th><th></th></tr></thead><tbody>@foreach($attempts as $item)<tr>@if($showStudent??false)<td>{{ $item->student->name }}</td><td>{{ $item->subject->title }}</td>@endif<td>#{{ $item->number }}</td><td>{{ ($item->submitted_at??$item->started_at)->format('d/m/Y H:i') }}</td><td><span class="pill {{ $item->status==='graded'?'good':'warning' }}">{{ $item->status_label }}</span></td><td class="grade-cell">{{ $item->score!==null?number_format($item->score,2,',','.'):'—' }}</td><td><a class="text-link" href="{{ auth()->user()->isAdmin()?route('admin.attempt',$item):route('attempt.show',$item) }}">{{ $item->status==='in_progress'?'Continuar':'Ver prova' }} →</a></td></tr>@endforeach</tbody></table></div>@endif
